# frozen_string_literal: true

RSpec.describe TimekeepingRules::ReservationDecision, ".call" do
  # "On a non-draft invoice the decision releases nothing (row L4: "On a
  # non-draft, the boundary sends no removal")." A caller that wrongly sends an
  # empty set for a sent invoice must not unlock the entries it holds.
  it "releases nothing when a non-draft invoice sends an empty desired set" do
    held = { invoice: :this, state: "committed", disposition: "active" }

    result = described_class.call(current: { 17 => [held], 18 => [held] }, desired: [],
                                  disposition: "active", invoice_status: "sent")

    expect(result.fetch(:release)).to eq([])
    expect(result.fetch(:reserve)).to eq([])
    expect(result.fetch(:conflicts)).to eq([])
  end
end

# frozen_string_literal: true
RSpec.describe TimekeepingRules::ReservationDecision, ".call" do
  # "A draft's removed line releases only entries no remaining direct or
  # grouped line references." The direct line for 12 was removed, but the
  # grouped line [12, 13] still holds it; only 14, which no line holds, goes.
  it "keeps an entry a remaining grouped line still references when its direct line is removed from a draft" do
    held = { invoice: :this, state: "committed", disposition: "active" }
    current = { 11 => [held], 12 => [held], 13 => [held], 14 => [held] }

    result = described_class.call(current:, desired: [11, [12, 13]], disposition: "active", invoice_status: "draft")

    expect(result.fetch(:release)).to eq([14])
  end
end

# frozen_string_literal: true
RSpec.describe TimekeepingRules::ReservationDecision, ".call" do
  # "An entry another kept invoice holds is refused: "Prepare is refused: the
  # entry is on another invoice."" An id absent from current (another
  # company's entry or none at all) must never be treated as free to reserve.
  it "answers a foreign or missing entry as not_found and never reserves it, while refusing one held by another active invoice" do
    other_active = { invoice: :other, state: "committed", disposition: "active" }
    current = { 21 => [], 22 => [other_active] }

    result = described_class.call(current:, desired: [21, 22, 999], disposition: "active", invoice_status: "draft")

    reasons = result.fetch(:conflicts).to_h { |conflict| [conflict.fetch(:entry_id), conflict.fetch(:reason).to_s] }
    expect(reasons).to eq(22 => "on_another_invoice", 999 => "not_found")
    expect(result.fetch(:reserve)).not_to include(22, 999)
  end
end

